import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    spend_mask = (
        (df['row_kind'] == 'on_book') &
        (df['Currency'] == 'USD') &
        (df['Amount'] < 0) &
        (~df['Transaction Type'].str.upper().isin([
            'TRANSFER', 'INTERNAL TRANSFER', 'FEE', 'FEES',
            'INTEREST', 'INTEREST CHARGE', 'PAYMENT'
        ]))
    )
    df_spend = df[spend_mask].copy()
    df_spend['_pd'] = pd.to_datetime(df_spend['Posting Date'])

    date_mask = (
        (df_spend['_pd'] >= '2026-08-01') &
        (df_spend['_pd'] < '2026-11-01')
    )
    df_window = df_spend[date_mask].copy()
    df_window['spend_abs'] = df_window['Amount'].abs()
    df_window['_month_str'] = df_window['_pd'].dt.strftime('%Y-%m')

    top_cats = (
        df_window.groupby('Merchant Category')['spend_abs']
        .count()
        .nlargest(10)
        .index.tolist()
    )
    df_top = df_window[df_window['Merchant Category'].isin(top_cats)].copy()

    # 1. Total spend by Merchant Category
    cat_spend = (
        df_top.groupby('Merchant Category')['spend_abs']
        .sum()
        .reset_index()
    )
    result['segments'].append({
        "segment_column": "Merchant Category",
        "metric_column": "Amount",
        "aggregation": "sum",
        "label": "spend_aug_oct_2026",
        "results": [
            {"name": str(r['Merchant Category']), "value": round(float(r['spend_abs']), 4)}
            for _, r in cat_spend.iterrows()
        ]
    })

    # 2. Spend by Merchant Category x Posting Date month
    #    segment_column uses real columns only; group names encode both dimensions
    cat_month = (
        df_top.groupby(['Merchant Category', '_month_str'])['spend_abs']
        .sum()
        .reset_index()
    )
    result['segments'].append({
        "segment_column": "Merchant Category|Posting Date",
        "metric_column": "Amount",
        "aggregation": "sum",
        "label": "spend_by_cat_month",
        "results": [
            {"name": f"{r['Merchant Category']}|{r['_month_str']}", "value": round(float(r['spend_abs']), 4)}
            for _, r in cat_month.iterrows()
        ]
    })

    # 3. Transaction count by Merchant Category
    cat_count = (
        df_top.groupby('Merchant Category')['spend_abs']
        .count()
        .reset_index()
    )
    result['segments'].append({
        "segment_column": "Merchant Category",
        "metric_column": "Amount",
        "aggregation": "count",
        "label": "txn_count_aug_oct_2026",
        "results": [
            {"name": str(r['Merchant Category']), "value": float(r['spend_abs'])}
            for _, r in cat_count.iterrows()
        ]
    })

    # 4. Mean spend per transaction by Merchant Category
    cat_mean = (
        df_top.groupby('Merchant Category')['spend_abs']
        .mean()
        .reset_index()
    )
    result['segments'].append({
        "segment_column": "Merchant Category",
        "metric_column": "Amount",
        "aggregation": "mean",
        "label": "avg_spend_per_txn_aug_oct_2026",
        "results": [
            {"name": str(r['Merchant Category']), "value": round(float(r['spend_abs']), 4)}
            for _, r in cat_mean.iterrows()
        ]
    })

    # 5. MoM trends per category (Aug->Sep, Sep->Oct)
    months_sorted = sorted(df_top['_month_str'].unique().tolist())
    pivot = (
        cat_month.pivot(index='Merchant Category', columns='_month_str', values='spend_abs')
        .fillna(0)
    )
    for i in range(1, len(months_sorted)):
        prev_m = months_sorted[i - 1]
        curr_m = months_sorted[i]
        if prev_m not in pivot.columns or curr_m not in pivot.columns:
            continue
        for cat in pivot.index:
            prev_val = float(pivot.loc[cat, prev_m])
            curr_val = float(pivot.loc[cat, curr_m])
            if prev_val > 0:
                pct = round((curr_val - prev_val) / prev_val * 100, 4)
                direction = "up" if pct > 0 else ("down" if pct < 0 else "flat")
                result['trends'].append({
                    "column": "Amount",
                    "period": "MoM",
                    "direction": direction,
                    "pct_change": pct,
                    "segment": str(cat)
                })

    n_rows = int(len(df_window))
    result['assumptions'].append(
        f"Spend = |Amount| where Amount<0, on_book, USD, txn_type not TRANSFER/FEE/INTEREST/PAYMENT; "
        f"Aug–Oct 2026; {n_rows} qualifying rows."
    )
    result['assumptions'].append(
        "Top 10 Merchant Categories by transaction count shown; MoM trends only where prior-month spend > 0."
    )
    result['assumptions'].append(
        "Derived '_month_str' column used only internally; segment_column references real columns only."
    )

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

